import numpy as np


def fit_centroids(X, y):
    X = np.array(X, dtype=float)
    centroids = {}
    for label in set(y):
        rows = [i for i in range(len(y)) if y[i] == label]
        centroids[label] = X[rows].mean(axis=0).tolist()
    return centroids


def predict_centroids(centroids, X):
    labels = sorted(centroids)
    out = []
    for x in np.array(X, dtype=float):
        dists = [float(np.sum((x - np.array(centroids[l])) ** 2)) for l in labels]
        out.append(labels[dists.index(min(dists))])
    return out


def fit_scaled_centroids(X, y):
    return {'means': [], 'stds': [], 'centroids': fit_centroids(X, y)}


def predict_scaled(model, X):
    return predict_centroids(model['centroids'], X)

